def mergeCharacters(s, k):
    # res is the already-merged prefix of the string
    res = []

    for ch in s:
        # The last k characters of res are the only ones within distance k of ch
        start = max(0, len(res) - k)
        close = False
        for i in range(start, len(res)):
            if res[i] == ch:
                close = True
                break
        # If an equal character is close on the left, ch merges into it (is dropped)
        if not close:
            res.append(ch)

    return ''.join(res)
